<parameter name="file_text">import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';
import { getDb } from './db.js';

const JWT_SECRET = 'your-secret-key-change-this';
const TOKEN_EXPIRY = '7d';
const MAX_FAILED_ATTEMPTS = 5;
const ATTEMPT_WINDOW_MINUTES = 15;

export async function signup(email, password) {
  const db = getDb();

  const hashedPassword = await bcrypt.hash(password, 10);

  try {
    await db.run(
      'INSERT INTO users (email, password) VALUES (?, ?)',
      [email, hashedPassword]
    );
    return { success: true, message: 'Signup successful' };
  } catch (err) {
    if (err.message.includes('UNIQUE constraint')) {
      return { success: false, error: 'Email already exists' };
    }
    throw err;
  }
}

export async function login(email, password) {
  const db = getDb();

  // Check rate limit
  const cutoffTime = new Date(Date.now() - ATTEMPT_WINDOW_MINUTES * 60000).toISOString();
  const recentAttempts = await db.get(
    'SELECT COUNT(*) as count FROM login_attempts WHERE email = ? AND attempted_at > ?',
    [email, cutoffTime]
  );

  if (recentAttempts.count >= MAX_FAILED_ATTEMPTS) {
    return { success: false, error: 'Too many failed attempts. Try again later.' };
  }

  const user = await db.get('SELECT * FROM users WHERE email = ?', [email]);

  if (!user) {
    await db.run('INSERT INTO login_attempts (email) VALUES (?)', [email]);
    return { success: false, error: 'Invalid email or password' };
  }

  const passwordMatch = await bcrypt.compare(password, user.password);

  if (!passwordMatch) {
    await db.run('INSERT INTO login_attempts (email) VALUES (?)', [email]);
    return { success: false, error: 'Invalid email or password' };
  }

  // Clear failed attempts on successful login
  await db.run(
    'DELETE FROM login_attempts WHERE email = ? AND attempted_at > ?',
    [email, cutoffTime]
  );

  const token = jwt.sign({ userId: user.id, email: user.email }, JWT_SECRET, {
    expiresIn: TOKEN_EXPIRY
  });

  return { success: true, token, userId: user.id };
}

export function verifyToken(token) {
  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    return { valid: true, data: decoded };
  } catch (err) {
    return { valid: false, error: err.message };
  }
}
